'use strict';
const KEY='psychology-learning-v2',OLD_KEY='psychology-combined-bank-v1',PAGE_SIZE=12;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={trend:'趋势解析',memory:'记忆练习',mnemonics:'口诀速记',predictions:'主观题预测',coverage:'覆盖与缺口',corrections:'笔记修正',sources:'权威来源',progress:'我的学习',sync:'账号与同步'};
let data={subjects:[],sources:[],knowledgePoints:[],memoryQuestions:[],predictions:[],corrections:[],predictionCoverage:[],mnemonicCards:[],trend:{}},view='trend',page=0,selected=new Map(),revealed=new Set();
let storageKey=KEY,syncTimer=null,syncGeneration=0,subscribed=false,loadGeneration=0,activeLoad=null,loadedManifest=null,checkingVersion=false,versionMessage='尚未读取题库',versionNew=false;
let state={version:2,answers:{},wrong:[],favorites:[],notes:{},legacyRecords:{},updatedAt:null};
let acceptedQuestionReviews=new WeakSet();
const isQuestion=x=>typeof x.prompt==='string'&&(Array.isArray(x.options)||Array.isArray(x.answer_points));
const displayQuestion=x=>window.NativeSubjectiveView?.project(x,data)||x;
const originalQuestion=x=>window.NativeSubjectiveView?.originalFor(x)||x;
function questionSubject(x){const base=(typeof x.subject==='string'||window.NativeSubjectiveView?.isNative(originalQuestion(x)))&&window.NativeSubjectiveView?window.NativeSubjectiveView.subject(originalQuestion(x),data):x.subject;if(Array.isArray(x.mappings)){const ids=currentCoverageIds(x.mappings.flatMap(m=>[m.question_id,...array(m.question_ids)]),'predictions'),subjects=[...new Set(ids.map(id=>questionSubject(coverageIndex.get(id).q)).filter(Boolean))];if(subjects.length===1)return subjects[0];if(subjects.length>1&&(x.domain==='methods'||base==='methods'))return 'methods'}return base}
const practiceDisabled=x=>x.practice_enabled===false||x.safe_for_quiz===false;
const verified=x=>isQuestion(x)?!practiceDisabled(x)&&acceptedQuestionReviews.has(originalQuestion(x)):['verified','reviewed','已核验','已审校','核验通过'].includes(x.review_status||x.verification_status);
const statusLabels={'reviewed':'核心答法已审校','verified':'已核验','needs-review':'待独立核验','authored-needs-review':'已编待审','partial-needs-review':'部分覆盖待审','uncovered':'尚未覆盖','excluded':'导航条目排除','limited-search-summary':'仅检索摘要'};
const status=x=>isQuestion(x)?practiceDisabled(x)?'导航/停用，不计练习':verified(x)?'当前整题独立审核通过':'当前整题独立审核证据待补':statusLabels[x.review_status||x.verification_status]||x.review_status||x.verification_status||'待核验';
const array=x=>Array.isArray(x)?x:[];
let displaySubjectsBank=null,displaySubjectsCache=[];
function displaySubjects(){if(displaySubjectsBank===data)return displaySubjectsCache;const rows=data.subjects,derived=data.predictions.some(q=>window.NativeSubjectiveView?.isNative(q)&&questionSubject(q)==='methods')||displayPredictionCoverage().some(t=>questionSubject(t)==='methods');displaySubjectsCache=derived&&!rows.some(s=>s.id==='methods')?[...rows,{id:'methods',title:'方法与测量（跨科／笔记外）'}]:rows;displaySubjectsBank=data;return displaySubjectsCache}
const subjectName=id=>displaySubjects().find(s=>s.id===id)?.title||id||'综合';
const urlSafe=url=>{try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?esc(u.href):''}catch{return ''}};
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4000)}
function object(v){return v&&typeof v==='object'&&!Array.isArray(v)}
function archiveHistoricalScores(result,raw){
 const bucket=Array.isArray(result.legacyRecords.score_history_v1)?result.legacyRecords.score_history_v1:[];
 for(const kind of ['answers','notes'])for(const [question_id,record] of Object.entries(raw[kind]||{})){
  if(!record||typeof record!=='object'||!['score','max_score','content_version','self_score','maxScore','contentVersion','scoring_version'].some(k=>Object.hasOwn(record,k)))continue;
  const entry={question_id,record_kind:kind,record:JSON.parse(JSON.stringify(record))};
  if(!bucket.some(old=>JSON.stringify(old)===JSON.stringify(entry)))bucket.push(entry);
 }
 if(bucket.length)result.legacyRecords.score_history_v1=bucket;
}

function validState(v){if(!object(v)||!object(v.answers)||!Array.isArray(v.wrong))throw Error('记录格式不正确');const result={version:2,answers:{},wrong:[],favorites:[],notes:{},legacyRecords:object(v.legacyRecords)?v.legacyRecords:{},updatedAt:typeof v.updatedAt==='string'?v.updatedAt:null};archiveHistoricalScores(result,v);for(const [id,a] of Object.entries(v.answers)){if(!object(a)||typeof a.correct!=='boolean'||!Number.isInteger(a.attempts)||a.attempts<1)continue;result.answers[id]={correct:a.correct,firstCorrect:typeof a.firstCorrect==='boolean'?a.firstCorrect:a.correct,attempts:a.attempts,selected:array(a.selected).filter(n=>Number.isInteger(n)&&n>=0),time:typeof a.time==='string'?a.time:''}}result.wrong=[...new Set(v.wrong.filter(id=>typeof id==='string'))];result.favorites=[...new Set(array(v.favorites).filter(id=>typeof id==='string'))];for(const [id,n]of Object.entries(v.notes||{})){if(object(n)&&typeof n.text==='string')result.notes[id]={text:n.text.slice(0,20000),time:typeof n.time==='string'?n.time:''}}return result}
function restore(){try{const saved=localStorage.getItem(storageKey);if(saved)state=validState(JSON.parse(saved))}catch{toast('本机记录读取失败，可通过导入恢复。')}}
function save(){if(syncStatus.readOnly)return toast('此窗口仅查看，不能修改账号记录。');state.updatedAt=new Date().toISOString();try{localStorage.setItem(storageKey,JSON.stringify(state));$('saveStatus').textContent='已保存至本机'}catch{$('saveStatus').textContent='保存失败 · 请导出';toast('浏览器存储不可用，请导出记录。')}metrics();if(syncStatus.authenticated){try{window.PsychSync.stageLocal(state)}catch(error){toast(error.message)}clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncCurrent(),1000)}}
function meta(x,isQuestion=false){return `<div class="meta">${isQuestion?`<span class="question-number">题号：${esc(x.id)}</span>`:''}<span class="tag">${esc(subjectName(questionSubject(x)))}</span><span class="tag ${verified(x)?'verified':'pending'}">${isQuestion?'题目审核：':data.sources.includes(x)?'来源审核：':'知识/覆盖审核：'}${esc(status(x))}</span>${isQuestion?'':`<span>${esc(x.id)}</span>`}</div>`}
function textBlock(v){return Array.isArray(v)?v.map(x=>`<p>${esc(x)}</p>`).join(''):`<p>${esc(v)}</p>`}
function references(x){
 const refs=array(x.note_refs),scoped=array(x.source_refs);
 const sources=scoped.length?scoped.map(r=>{const base=data.sources.find(s=>s.id===r.id)||{};return {...base,...r,quote:r.short_quote||'',scoped:true}}):array(x.source_ids).map(id=>data.sources.find(s=>s.id===id)).filter(Boolean);
 return `<details class="details"><summary>笔记定位与权威来源（${refs.length+sources.length}）</summary>${isQuestion(x)&&!refs.length?'<p class="fine">外源补充／订正训练：未提供准确笔记原文锚点，不硬绑定笔记或宣称原笔记覆盖。</p>':''}${!refs.length&&!sources.length?'<p class="fine">尚未绑定来源，不能视为已完成追溯。</p>':''}${refs.map(r=>`<div class="reference"><b>${esc(r.file_name)}</b> · ${esc(r.locator)}${r.basis_type?`<p>${esc(r.basis_type)}</p>`:''}${r.excerpt?`<blockquote>“${esc(r.excerpt)}”</blockquote>`:''}${r.role?`<p class="fine">${esc(r.role)}</p>`:''}<button class="btn" data-open-note="${esc(String(r.locator||'').replace(/^audit:/,''))}">查看相关笔记原文</button></div>`).join('')}${sources.map(s=>`<div class="reference">${sourceLink(s)}<p>${esc(s.summary)}</p>${s.quote?`<blockquote>“${esc(s.quote)}”</blockquote>`:s.scoped&&!array(s.original_excerpts).length?'<p class="fine">本条来源的准确短摘仍待补核。</p>':''}${array(s.original_excerpts).filter(e=>e.quote&&e.quote!==s.quote).map(e=>`<blockquote>“${esc(e.quote)}”</blockquote><p class="fine">${esc(e.locator||'')} · ${esc(e.supports||'')}</p>`).join('')}<span class="fine">${esc(s.organization)} · ${esc(s.verification_status||'待核验')}</span>${s.verification_scope?`<p class="fine">事实支持范围：${esc(s.verification_scope)}</p>`:''}${s.scoped?`<p class="fine">短摘状态：${esc(s.excerpt_verification_status||'未记录')}；短摘核验不代表本题全部核准。</p>${s.excerpt_scope?`<p class="fine">短摘阅读范围：${esc(s.excerpt_scope)}</p>`:''}`:''}</div>`).join('')}</details>`
}
function sourceLink(s){const url=urlSafe(s.url);return url?`<a href="${url}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:`<b>${esc(s.title)}</b> <span class="fine">链接尚未提供</span>`}
function variations(x){return array(x.variations).length?`<h3>换一种考法</h3><ul>${x.variations.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:''}
function favoriteButton(x){return `<button class="btn" data-favorite="${esc(x.id)}" aria-pressed="${state.favorites.includes(x.id)}">${state.favorites.includes(x.id)?'★ 已收藏':'☆ 收藏'}</button>`}
function forecastRange(question){const range=displayQuestion(question)?.forecast?.knowledge_point_range;return Array.isArray(range)&&range.length===2&&range.every(n=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=100)&&range[0]<=range[1]?range:null}
function probabilityMatches(question,choice){if(!choice||choice==='all')return true;const range=forecastRange(question);if(choice==='unmarked')return !range;if(!range)return false;const bands={'0-30':[0,30],'30-60':[30,60],'60-100':[60,100]},band=bands[choice];return !!band&&range[0]<=band[1]&&range[1]>=band[0]}
function cardSubjects(c){return [...new Set([c.subject,...array(c.subjects)].filter(Boolean))]}
function cardChapters(c,subject){const rows=array(c.chapters).filter(r=>!subject||subject==='all'||r.subject===subject);return [...new Set([...rows.map(r=>typeof r==='string'?r:r.chapter),...(!subject||subject==='all'||c.subject===subject?[c.chapter]:[])].filter(Boolean))]}
function mnemonicMatches(c){const subject=$('subject').value,chapter=$('mnemonicChapter').value,search=$('search').value.trim().toLowerCase();return (subject==='all'||cardSubjects(c).includes(subject))&&(chapter==='all'||cardChapters(c,subject).includes(chapter))&&(!search||JSON.stringify(c).toLowerCase().includes(search))}
function updateMnemonicChapters(reset=false){const el=$('mnemonicChapter');if(!el)return;const previous=reset?'all':el.value,subject=$('subject').value,chapters=[...new Set(data.mnemonicCards.filter(c=>subject==='all'||cardSubjects(c).includes(subject)).flatMap(c=>cardChapters(c,subject)))];el.innerHTML='<option value="all">全部章节</option>'+chapters.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('');el.value=chapters.includes(previous)?previous:'all'}
function mnemonicCard(c){const p=c.provenance||{},fix=c.correction||{},display=c.display||{},warning=display.warning||(display.recommended_for_memorization===false?'原句保留作核对，不宜直接背诵':'');const refs=array(c.source_refs).map(ref=>typeof ref==='string'?data.sources.find(s=>s.id===ref):({...data.sources.find(s=>s.id===(ref.source_id||ref.id)),...ref,quote:ref.short_quote??ref.quote??''})).filter(Boolean);const urls=[...new Set(array(fix.source_urls))];return '<article class="card mnemonic-card" data-mnemonic-id="'+esc(c.id)+'"><div class="meta"><span class="tag">'+esc(cardSubjects(c).map(subjectName).join(' · '))+'</span><span>'+esc(c.id)+'</span><span class="tag">'+esc(p.display_label||'口诀阅读')+'</span></div><h2>'+esc(c.title)+'</h2><p class="fine">'+esc(cardChapters(c,'all').join(' · '))+'</p>'+(warning?'<div class="mnemonic-warning" role="note"><strong>背诵警示</strong><p>'+esc(warning)+'</p></div>':'')+'<p class="mnemonic-text">'+esc(c.mnemonic)+'</p><dl class="mnemonic-parts">'+array(c.meaning_parts).map(m=>'<div><dt>'+esc(m.cue)+'</dt><dd>'+esc(m.meaning)+'</dd></div>').join('')+'</dl>'+(c.usage?'<h3>怎么使用</h3><p>'+esc(c.usage)+'</p>':'')+(array(c.cautions).length?'<div class="mnemonic-cautions"><h3>注意边界</h3><ul>'+c.cautions.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul></div>':'')+(fix.original_issue?'<p class="mnemonic-warning"><strong>原文问题：</strong>'+esc(fix.original_issue)+'</p>':'')+(fix.explanation?'<h3>整理与修正</h3><p>'+esc(fix.explanation)+'</p>':'')+(fix.verification_scope?'<p class="fine">外部核验范围：'+esc(fix.verification_scope)+'</p>':'')+'<details class="details"><summary>原笔记定位与来源</summary><p>'+esc(p.note_file)+' · '+esc(p.location)+'</p>'+(p.quote?'<blockquote>'+esc(String(p.quote).slice(0,80))+'</blockquote>'+(String(p.quote).length>80?'<p class="fine">原文短引已截短，仅展示前80字符；完整定位见上方笔记位置。</p>':''):'')+refs.map(r=>'<div class="reference">'+sourceLink(r)+'<p class="fine">'+esc(r.verification_scope||r.claim_scope||r.evidence_scope||r.scope||r.summary||'')+'</p>'+((r.quote||r.short_quote)?'<blockquote>'+esc(r.quote||r.short_quote)+'</blockquote>':'')+'</div>').join('')+urls.filter(u=>!refs.some(r=>r.url===u)).map(u=>{const safe=urlSafe(u);return safe?'<p><a href="'+safe+'" target="_blank" rel="noopener noreferrer">'+esc(u)+' ↗</a></p>':'<p class="fine">来源链接格式不可用</p>'}).join('')+'</details></article>'}
function matches(x){if(view==='mnemonics')return mnemonicMatches(x);if(view==='predictions'&&!probabilityMatches(x,$('examProbability')?.value))return false;const s=$('subject').value,r=$('review').value,p=$('practice').value,q=$('search').value.trim().toLowerCase();if(!['sources','trend'].includes(view)&&s!=='all'&&questionSubject(x)!==s)return false;if(r==='verified'&&!verified(x)||r==='pending'&&verified(x))return false;if(['memory','predictions'].includes(view)&&(p==='wrong'&&!state.wrong.includes(x.id)||p==='favorites'&&!state.favorites.includes(x.id)||p==='unseen'&&x.id!==activeCardId&&(state.answers[x.id]||state.notes[x.id])))return false;return !q||JSON.stringify(x).toLowerCase().includes(q)||array(x.source_refs).some(r=>{const s=data.sources.find(s=>s.id===r.id)||{};return [r.title||s.title,r.url||s.url].filter(Boolean).join(' ').toLowerCase().includes(q)})}
function currentCoverageSummary(raw,accepted){
 const summary=raw.finiteLearningEvidenceSummary,rows=raw.finiteLearningEvidenceRecords,classes=['concrete_bounded_answer_with_source_limits','specific_original_unverified_related_aid_not_counted_as_target_taught','unidentified_fragment_or_unelaborated_label_excluded_from_certified_knowledge'];
 if(summary?.schema!=='fixed235-specific-evidence-not-blanket-A-v1'||!Array.isArray(rows)||!rows.length||summary.row_count!==rows.length||!Array.isArray(summary.literal_errors)||summary.literal_errors.length)return null;
 const questions=new Map([...array(raw.predictions),...array(raw.memoryQuestions)].map(q=>[q.id,q])),counts=Object.fromEntries(classes.map(k=>[k,0])),ids=new Set();let checks=0,valid=true;
 function inspect(x){if(!x||typeof x!=='object')return;if(Array.isArray(x)){x.forEach(inspect);return}const id=x.qID||x.question_id,ap=x.AP_index??x.AP??x.answer_point_index_1based,quote=x.actual_answer_quote??x.exact_current_short_answer_quote??x.actual_answer_verbatim;
  if(id&&ap&&quote){const q=questions.get(id),point=q?.answer_points?.[ap-1];checks++;if(!q||!accepted?.has(q)||!Number.isInteger(ap)||ap<1||typeof quote!=='string'||typeof point?.point!=='string'||!point.point.includes(quote))valid=false}
  if(id&&Array.isArray(x.actual_correct_options)){const q=questions.get(id);checks++;if(!q||!accepted?.has(q)||JSON.stringify(x.actual_correct_options)!==JSON.stringify(array(q.answer).map(i=>q.options[i]))||x.actual_plain_explanation!==q.plain_explanation)valid=false}
  Object.values(x).forEach(inspect);
 }
 for(const row of rows){if(typeof row.target_id!=='string'||ids.has(row.target_id)||!classes.includes(row.delivery_evidence_class))return null;ids.add(row.target_id);counts[row.delivery_evidence_class]++;inspect(row.authored_evidence)}
 if(!valid||checks!==summary.literal_AP_or_MC_evidence_checks||classes.some(k=>counts[k]!==summary.evidence_class_counts?.[k]))return null;
 const finite=raw.effectiveKnowledgeCoverage?.finite_learning_action_closeout,scope=raw.effectiveKnowledgeCoverage;const finiteScopeComplete=finite?.original_queue_handled===rows.length&&Array.isArray(finite.pending_source_confirmed_valid_teaching_branch_ids)&&finite.pending_source_confirmed_valid_teaching_branch_ids.length===0&&scope.known_confirmed_uncovered_count===0&&Array.isArray(scope.known_confirmed_uncovered_ids)&&scope.known_confirmed_uncovered_ids.length===0;return {rows:rows.length,bounded:counts[classes[0]],originalUnverified:counts[classes[1]],fragments:counts[classes[2]],checks,finiteScopeComplete};
}
function coverageStatusNotice(){if(!data.version)return '';const legacy=data.knowledgePoints.filter(k=>k.gap_reason||!verified(k)).length,c=data.coverageSummary;
 return `<section class="coverage-status" aria-label="当前版本覆盖口径"><p><strong>${c?.finiteScopeComplete?'已识别的有限补教范围已完成。':'本版知识覆盖以旧台账与具体答点为准。'}</strong> 当前加载：${esc(data.version)}。</p>${c?`<p>本包 ${c.rows} 条专项审校记录：${c.bounded} 条有有限教答；${c.originalUnverified} 条原笔记具体断言仍未核实；${c.fragments} 条残片或未展开标签不计作已确认知识。补教不等于原句全文正确，以上不是全部知识点的统计。全域独立知识命题总量尚未核定，不据此报无条件全域缺口为零。</p>`:'<p>本版本没有可核对当前答文的专项审校摘要，原笔记疑点与残片数量未核定；需更新资料后才能显示对应摘要。不会借其他版本的数据替本库作结论。</p>'}<details><summary>旧簇待复核统计：${legacy} 条</summary><p>这是旧知识簇的“未覆盖、部分覆盖或待核验”混合状态，不是 ${legacy} 个已确认缺教知识点，也不能由整题审核通过数推定归零。旧簇台账保留作定位，按当前题目和具体证据范围学习。</p></details></section>`;
}
function metrics(){const all=[...data.memoryQuestions,...data.predictions].filter(q=>!practiceDisabled(q)),checked=all.filter(verified).length,answered=data.memoryQuestions.filter(q=>state.answers[q.id]).length;const reviewNotice=$('contentReviewStatus');if(reviewNotice)reviewNotice.textContent=data.version?'当前加载：'+data.version+'。'+(all.length&&checked===all.length?'当前可练题整题审校已完成':'当前可练题的整题审校凭据未齐备')+'（'+checked+' / '+all.length+'）。知识覆盖与原笔记疑点另列下方；原文仍保留需订正内容。概率为主观判断，非统计校准。':'尚未加载题库；读取后显示当前版本的可练题审校状态。';$('metrics').innerHTML=[['当前题目条目',all.length],['整题审核通过',checked],['本机已作答（含历史）',answered],[data.coverageSummary?.finiteScopeComplete?'已识别补教范围':'知识覆盖说明',data.coverageSummary?.finiteScopeComplete?'已完成':'旧统计待复核']].map(([s,n])=>`<div class="metric"><b>${esc(n)}</b><span>${s}</span></div>`).join('');let notice=$('coverageStatus');if(!notice){notice=document.createElement('div');notice.id='coverageStatus';$('metrics').after(notice)}notice.innerHTML=coverageStatusNotice()}

function empty(title='暂无符合筛选的内容',body='可调整学科、核验状态或搜索条件。'){return `<div class="empty"><h2>${title}</h2><p>${body}</p></div>`}
function memory(q){const picked=selected.get(q.id)||[],show=revealed.has(q.id),ans=array(q.answer),record=state.answers[q.id];return `<article class="card" data-id="${esc(q.id)}">${meta(q,true)}<h2>${esc(q.prompt)}</h2><div class="options" role="group" aria-label="选择答案">${array(q.options).map((o,i)=>`<button class="option ${picked.includes(i)?'selected':''} ${show&&verified(q)?ans.includes(i)?'correct':picked.includes(i)?'incorrect':'':''}" data-choice="${esc(q.id)}" data-index="${i}" aria-pressed="${picked.includes(i)}" ${show?'disabled':''}><b>${String.fromCharCode(65+i)}</b><span>${esc(typeof o==='string'?o:o.text)}</span></button>`).join('')}</div><p class="fine">${ans.length>1?'多选':'单选'} · ${verified(q)?'已核验，可计入本机练习进度':'待核验内容只供查看，不计已练和正确率'}${record?` · 已练 ${record.attempts} 次`:''}</p><div class="actions"><button class="btn primary" data-submit="${esc(q.id)}" ${!picked.length||show?'disabled':''}>${verified(q)?'提交并查看解析':'查看暂定答案'}</button>${favoriteButton(q)}<button class="btn" data-wrong="${esc(q.id)}">${state.wrong.includes(q.id)?'移出错题':'加入错题'}</button>${show?`<button class="btn" data-retry="${esc(q.id)}">再练一次</button>`:''}</div>${show?`<div class="answer"><h3>${verified(q)?'答案':'暂定答案 · 仍待核验'}：${ans.map(i=>String.fromCharCode(65+i)).join('、')}</h3>${textBlock(q.plain_explanation)}<h3>逐项解释</h3><ul>${array(q.option_explanations).map((e,i)=>`<li><b>${String.fromCharCode(65+i)}</b> ${esc(e)}</li>`).join('')}</ul>${variations(q)}${q.independent_review?.evidence||q.review_evidence?`<p class="fine">审校依据：${esc(q.independent_review?.evidence||(typeof q.review_evidence==='object'?JSON.stringify(q.review_evidence):q.review_evidence))}</p>`:''}</div>`:''}${references(q)}</article>`}
function answerPointText(value){
 const same=(a,b)=>String(a??'').normalize('NFKC').replace(/\s+/g,'')===String(b??'').normalize('NFKC').replace(/\s+/g,'');
 if(value&&typeof value==='object'){const point=String(value.point??''),explanation=String(value.explanation??''),label=String(value.label??'');let body=point||explanation||label;if(label&&!same(label,body))body=label+'：'+body;const score=value.marks??value.training_score;return body+(score!==undefined?'（训练分值 '+score+'）':'')}
 const text=String(value??''),match=text.match(/(（训练分值\s*[^（）]+）)$/),suffix=match?.[1]||'',body=suffix?text.slice(0,-suffix.length):text;
 for(let i=0;i<body.length;i++){if(!'：:'.includes(body[i]))continue;const left=body.slice(0,i).trim(),right=body.slice(i+1).trim();if(left.length>=12&&same(left,right))return left+suffix}return text;
}
function answerPointExtra(value){if(!value||typeof value!=='object')return '';if(value.incremental_explanation)return String(value.incremental_explanation);const point=String(value.point??''),explanation=String(value.explanation??''),normalize=s=>s.normalize('NFKC').replace(/\s+/g,'');return point&&explanation&&normalize(point)!==normalize(explanation)?explanation:''}
function v13PointEvidence(q,index){const e=array(q.v13DisplayEvidence).find(e=>e.index===index);if(!e)return '';return `<details class="details v13-point-evidence" data-point-index="${index}"><summary>第${index}点：笔记与来源范围</summary>${e.note_refs.map(n=>`<div class="reference"><b>${esc(n.file_name)}</b> · ${esc(n.locator)}${n.excerpt?`<blockquote>${esc(n.excerpt)}</blockquote>`:''}<p class="fine">${esc(n.role)}</p><button class="btn" data-open-note="${esc(n.locator)}">查看相关笔记原文</button></div>`).join('')}${e.note_gap?`<p class="fine">${esc(e.note_gap)}</p>`:''}${!e.source_refs.length?`<p class="fine">本答点准确短摘尚未提供；仅保留真实笔记与应用边界，不采用全局通用引文替代。</p>`:''}${e.source_refs.filter(r=>!r.is_further_reading_only).concat(e.source_refs.filter(r=>r.is_further_reading_only)).map(r=>`<div class="reference v13-source-evidence ${r.is_further_reading_only?'v13-further-reading':''}">${r.is_further_reading_only?'<h4>进一步阅读（非本点直接证据）</h4>':''}${sourceLink(r)}<p class="fine">定位：${esc(r.excerpt_scope||r.locator||'包内未提供精确位置')}</p><p class="fine">包内支持范围：${esc(r.verification_scope||'未提供具体范围，不能当作答点已支持')}</p>${r.short_quote?`<blockquote>${esc(r.short_quote)}</blockquote>`:`<p class="fine">${r.quote_hold?'同一来源联合引文预算待分配，本次不扩展短引。':'本答点准确短摘尚未提供；不采用全局通用引文替代。'}</p>`}${array(r.original_excerpts).map(x=>`<blockquote>${esc(x.quote)}</blockquote><p class="fine">定位：${esc(x.locator||r.excerpt_scope)} · ${esc(x.support_scope||x.supports||'仅该题点包内记录')}</p>`).join('')}<p class="fine">${esc(r.evidence_limit||'')}</p><p class="fine">${esc(r.verification_status)}；仅展示包内记录，非本次事实核准。</p></div>`).join('')}${e.boundary?`<p class="fine">理论与应用边界：${esc(e.boundary)}</p>`:''}</details>`}
function v13AnswerPoint(q,p,i){if(!q.native_schema_v13)return `<li><span class="answer-point-text">${esc(answerPointText(p))}</span>${answerPointExtra(p)?`<p class="fine">补充解释：${esc(answerPointExtra(p))}</p>`:''}</li>`;const body=typeof p==='string'?p:String(p.point||p.explanation||''),score=object(p)?p.marks??p.training_score:undefined;return `<li class="v13-answer-point" data-answer-index="${i+1}">${p.label?`<b class="answer-point-label">${esc(p.label)}</b>`:''}<span class="answer-point-text">${esc(body)}</span>${Number.isFinite(score)?`<span class="answer-point-marks">训练分值 ${esc(score)}（自拟参考）</span>`:''}${p.scoring_criteria?.length?`<details class="v13-scoring-criteria"><summary>本点评分细则（自拟参考）</summary>${p.scoring_criteria.map(c=>`<p>${esc(variantText(c))}</p>`).join('')}</details>`:''}${p.scoring_subcriteria?.length?`<details class="v13-scoring-subcriteria"><summary>本点子评分规则（自拟参考）</summary>${p.scoring_subcriteria.map(c=>`<p>${esc(variantText(c))}</p>`).join('')}</details>`:''}${v13PointEvidence(q,i+1)}</li>`}
function v13AnswerSections(q){return `${array(q.native_marking_guidance).length?`<details class="v13-marking-guidance"><summary>评分参考说明</summary>${q.native_marking_guidance.map(g=>`<p>第${esc(g.indexes.join('、'))}点：${esc(g.text)}</p>`).join('')}</details>`:''}${array(q.answer_outline).length?`<section class="v13-outline"><h3>答题提纲</h3><ol>${q.answer_outline.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></section>`:''}${array(q.answer_cautions).length?`<section class="v13-cautions" role="note"><h3>作答注意与边界</h3><ul>${q.answer_cautions.map(t=>`<li>${esc(v13CautionText(t))}</li>`).join('')}</ul></section>`:''}${array(q.answer_extensions).length?`<section class="v13-extensions"><h3>拓展阅读</h3>${q.answer_extensions.map(e=>`<article class="v13-extension"><h4>${esc(e.title)}</h4><p class="fine">${e.scored===false?'不计本题分值':'包内未明确计分属性，未计入当前总分'}${e.coverage_role==='context_only'?' · 上下文补充，不计主问完整覆盖':''}</p><div class="v13-extension-content">${esc(e.content)}</div>${array(e.source_ids).map(id=>{const s=data.sources.find(s=>s.id===id)||{title:id};return `<div class="reference">${sourceLink(s)}<p class="fine">仅来源注册信息；没有题点匹配短摘时不展示全局引文。</p></div>`}).join('')}${array(e.source_note_ids).map(id=>`<button class="btn" data-open-note="${esc(id)}">查看笔记 ${esc(id)}</button>`).join('')}${array(e.related_question_ids).map(id=>`<button class="btn" data-open-question="${esc(id)}">关联题 ${esc(id)}</button>`).join('')}</article>`).join('')}</section>`:''}`}

function variantText(x){if(typeof x==='string')return x;if(Array.isArray(x))return x.map(variantText).filter(Boolean).join('；');if(x&&typeof x==='object')return Object.entries(x).map(([k,v])=>`${v13FieldLabel(k)}：${variantText(v)}`).join('；');return x==null?'':String(x)}
function v13Variants(q){if(!q.native_schema_v13)return variations(q);return array(q.native_variants).length?`<details class="details v13-variants"><summary>变式考法与不同条件</summary>${q.native_variants.map(v=>`<div class="reference v13-variant"><b>${esc(v.prompt)}</b>${Object.entries(v).filter(([k])=>k!=='prompt').map(([k,x])=>`<p class="fine" data-variant-field="${esc(k)}">${esc(v13FieldLabel(k))}：${esc(variantText(x))}</p>`).join('')}</div>`).join('')}</details>`:''}

function v13FieldLabel(k){return ({scored:'是否计分',display_role:'展示用途',answer_availability:'答案提供范围',answer_reference:'答案承接',inherits_answer_point_indexes:'沿用主答案要点',answer_point_indexes:'主答案要点',question_id:'关联题号',reference_answer:'变式新增答案',answer_delta:'变式增量',key_answer:'关键答案',additional_key_answer:'额外关键答案',requires_additional_knowledge:'需要补充知识',additional_answer_references:'额外关联答案',answer_scope:'变式答案范围',changes_required:'条件或重点变化',key_application:'应用要点',index_base:'序号从此数起',usage:'使用说明',criterion:'评分要求',marks:'训练分值',required:'要求',subcriterion_id:'子规则编号',reference_answers:'关联答案'})[k]||k}

function v13CautionText(t){return typeof t==='string'?t:[t.title,t.content||t.text,t.scored===false?'不计本题分值':'',t.target_id?'待核范围编号：'+t.target_id:''].filter(Boolean).join(' · ')}

function prediction(q){q=displayQuestion(q);const f=q.forecast||{},range=forecastRange(q)||[],shown=revealed.has(q.id);return `<article class="card" data-id="${esc(q.id)}">${meta(q,true)}<h2>${esc(q.title||q.prompt)}</h2><p class="prompt">${esc(q.prompt)}</p><div class="probability"><div>知识点在${esc(f.target||'下一次考试')}出现<strong>${range.length===2?`${esc(range[0])}–${esc(range[1])}%`:'未估计'}</strong>${esc(f.label||'主观判断，非统计校准')}</div></div><p class="fine">事件口径：${esc(f.event||'狭主题作为实质考点')}<br>依据：${esc(f.basis||'待补充')}<br>不确定性：${esc(f.uncertainty||'待补充')}</p>${q.external_supplement?`<div class="notice"><p>复习优先级：${esc(q.external_supplement.priority||'未标注')}</p>${[q.external_supplement.scope_notice,q.external_supplement.probability_scope_notice].filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:''}<div class="actions"><button class="btn primary" data-reveal="${esc(q.id)}">${shown?'收起答案要点':verified(q)?'查看答案要点':'查看待审要点'}</button>${favoriteButton(q)}</div>${shown?`<div class="answer">${Number.isFinite(q.training_marks??q.scoring?.total)?`<p class="fine">当前训练总分：${esc(q.training_marks??q.scoring.total)}（非官方分值）</p>`:''}${q.scoring_note?`<p class="fine">当前评分说明：${esc(q.scoring_note)}</p>`:''}<h3>${verified(q)?'作答要点':'作答要点（待整题审核，仅作审校参考）'}</h3><ul>${array(q.answer_points).map((p,i)=>v13AnswerPoint(q,p,i)).join('')}</ul>${v13AnswerSections(q)}<h3>通俗解析</h3>${textBlock(q.plain_explanation)}${v13Variants(q)}</div>`:''}<details class="details"><summary>写下我的作答（仅本机）</summary><label>先回忆，再对照要点<textarea data-note="${esc(q.id)}" rows="6" style="display:block;width:100%;margin-top:10px;border:1px solid var(--line);border-radius:8px;padding:12px;font:inherit" placeholder="写下论证结构、关键概念与例子…">${esc(state.notes[q.id]?.text||'')}</textarea></label></details>${references(q)}</article>`}
let coverageViewsBank=null,coverageViewsCache=[];
function displayPredictionCoverage(){
 if(coverageViewsBank===data)return coverageViewsCache;
 const rows=data.predictionCoverage.map(t=>({...t,mappings:array(t.mappings).filter(m=>currentCoverageIds([m.question_id],'predictions').length)})),byId=new Map(rows.map(t=>[t.id,t]));
 for(const q of data.predictions){if(practiceDisabled(q))continue;for(const m of array(q.coverage_targets)){
  const t=byId.get(m.target_id),indexes=array(m.answer_point_indexes);
  if(!t||m.question_id!==q.id||!indexes.length||!indexes.every(i=>Number.isInteger(i)&&i>0&&i<=array(q.answer_points).length))continue;
  if(t.mappings.some(old=>old.question_id===q.id&&JSON.stringify(old.answer_point_indexes)===JSON.stringify(indexes)))continue;
  t.mappings.push({...m,counts_as_full_coverage:false,display_forward_mapping:true});
 }}
 coverageViewsBank=data;coverageViewsCache=rows;return rows;
}
let coverageIndexBank=null,coverageIndex=new Map();
function currentCoverageIds(ids,kind){if(coverageIndexBank!==data){coverageIndexBank=data;coverageIndex=new Map([...data.memoryQuestions.map(q=>[q.id,{q,kind:'memory'}]),...data.predictions.map(q=>[q.id,{q,kind:'predictions'}])])}return [...new Set(array(ids))].filter(id=>{const entry=coverageIndex.get(id);return entry&&!practiceDisabled(entry.q)&&(!kind||entry.kind===kind)})}
function coverageLinks(ids){return currentCoverageIds(ids).map(id=>`<button class="btn" data-open-question="${esc(id)}">${esc(id)}${verified(coverageIndex.get(id).q)?'':' · 待核'}</button>`).join(' ')}
function coverage(k){const counts=k.coverage_counts||{},memoryIds=currentCoverageIds(k.memory_question_ids,'memory'),predictionIds=currentCoverageIds(k.prediction_ids,'predictions'),advertised=[...array(k.memory_question_ids),...array(k.prediction_ids)],missing=[...new Set(advertised)].filter(id=>!currentCoverageIds([id]).length);return `<article class="card"><div class="coverage-row"><div>${meta(k).replace('知识/覆盖审核：','旧簇审核标记：')}<h2>${esc(k.title)}</h2></div><span class="tag">${memoryIds.length} 记忆题 · ${predictionIds.length} 主观题</span></div><p class="fine">当前版本关联 ${memoryIds.length+predictionIds.length} 条：整题审核已绑定 ${[...memoryIds,...predictionIds].filter(id=>verified(coverageIndex.get(id).q)).length} 条；待核 ${[...memoryIds,...predictionIds].filter(id=>!verified(coverageIndex.get(id).q)).length} 条。关联数量不等于细分目标已完整覆盖。</p><p class="fine">旧细分目标统计（未与本轮专项审校合并）：${Object.entries(counts).map(([s,n])=>`${esc(statusLabels[s]||s)} ${n}`).join(' · ')}</p>${k.gap_reason?`<p class="pending" style="padding:12px;border-radius:6px">旧簇待复核说明（非已确认缺教）：${esc(k.gap_reason)}</p>`:''}${predictionIds.length?`<div class="coverage-prediction-links"><h3>簇级关联主观题</h3><p class="fine">当前题库实际可查条目；簇级关联不代表每个细分目标均已完整覆盖。精确目标支持范围见该题台账。</p>${coverageLinks(predictionIds)}</div>`:'<p class="fine">当前版本没有可查的簇级关联主观题；不以候选或历史题补计。</p>'}${missing.length?`<p class="fine">台账关联中 ${missing.length} 个题号在当前版本不存在或已停用：${esc(missing.join('、'))}。未计入上方条目数。</p>`:''}<details class="details"><summary>逐项查看 ${array(k.targets).length} 个细分目标</summary>${array(k.targets).map(t=>{const linked=[...array(t.question_ids),...array(t.prediction_ids)],valid=currentCoverageIds(linked);return `<div class="reference"><b>${esc(t.id)}</b> · ${esc(statusLabels[t.status]||t.status)}<p>${esc(t.label)}</p>${t.gap_reason?`<p class="fine">${esc(t.gap_reason)}</p>`:''}<p>${coverageLinks(valid)}</p>${linked.length!==valid.length?'<p class="fine">部分台账题号当前不可查，未作为有效题目链接。</p>':''}</div>`}).join('')}</details>${references(k)}</article>`}

function essayCoverage(t){
 t=displayPredictionCoverage().find(row=>row.id===t.id)||t;
 const labels={'direct_main':'题干直接考查','direct_subquestion':'子问直接考查','answer_component':'答案组成点','untested':'未覆盖','pending_verification':'待核验','excluded_context':'上下文/导航排除'};
 const completeness=t.counts_as_full_coverage===false?'不计完整覆盖':t.counts_as_full_coverage===true?(verified(t)?'已核准训练目标覆盖，原断言须另辨':'候选计完整覆盖，尚待独立核准'):'完整覆盖口径未确认';
 return `<article class="card">${meta(t)}<h2>${esc(t.title)}</h2><p>${esc(labels[t.release_coverage_role||t.coverage_role]||t.release_coverage_role||t.coverage_role)} · ${esc(t.source_locator)}</p><p class="fine">${esc(completeness)}</p>${array(t.joint_coverage_requires_all_question_ids).length?`<p class="fine">联合覆盖须同时具备全部关联题：${t.joint_coverage_requires_all_question_ids.map(esc).join('、')}</p>`:''}${t.original_claim_verified===false?'<p class="fine">原笔记断言未经核准，按限定或订正后的训练目标复习。</p>':''}${t.scope_limit?`<p class="fine">${esc(t.scope_limit)}</p>`:''}${t.gap_reason?`<p class="fine">${esc(t.gap_reason)}</p>`:''}${array(t.mappings).map(m=>`<div class="reference"><button class="btn" data-open-question="${esc(m.question_id)}">${esc(m.question_id)}${verified(coverageIndex.get(m.question_id)?.q||{})?'':' · 待核'}</button><p>${esc(m.prompt_clause)}</p><p class="fine">训练评分点：${array(m.answer_point_indexes).map(esc).join('、')}${m.counts_as_full_coverage===false?' · 本映射不计完整覆盖':''}${m.display_forward_mapping?' · 当前题明确目标的有限显示关联，未更改原台账状态':''}</p>${m.support_scope?`<p class="fine">${esc(m.support_scope)}</p>`:''}</div>`).join('')}${array(t.held_mappings).length?`<details class="details"><summary>另有 ${array(t.held_mappings).length} 条待核映射，未计覆盖</summary>${t.held_mappings.map(m=>`<p>${esc(m.question_id)} · ${esc(m.local_hold_reason||'当前题干或评分点映射待核')}</p>`).join('')}</details>`:''}${t.outside_notes?'<p class="fine">笔记外权威补充，未冒充笔记覆盖</p>':''}</article>`
}

function correction(x){const summary=x.before_type==='issue-summary';return `<article class="card">${meta(x)}<h2>${esc(x.title)}</h2><p class="fine">${summary?'待审问题摘要（非原笔记逐字引用）':'原笔记表述'}</p>${summary?textBlock(x.before):`<blockquote>${esc(x.before)}</blockquote>`}<div class="answer"><h3>建议修正</h3>${textBlock(x.after)}<h3>修正依据</h3>${textBlock(x.reason)}</div>${references(x)}</article>`}
